# -*- coding: utf-8 -*-
# 追加 形容词+副词（topicId=5）100 题到 english-paper-1000.js（一次性脚本，幂等）
import io

def esc(s):
    return (s.replace('\\', '\\\\').replace('"', '\\"')
             .replace('\n', '\\n'))

qs = []
def fill(i, q, ans, why):
    qs.append('    { id: "p1000-%03d", subject: "english", module: "paper1000", topicId: 5, type: "fill",\n      q: "%s",\n      ansText: "%s",\n      why: "%s",\n      source: "语法1000题·形容词+副词" }' % (i, esc(q), esc(ans), esc(why)))

def cho(i, q, o, a, why):
    opts = ", ".join('"%s"' % esc(x) for x in o)
    qs.append('    { id: "p1000-%03d", subject: "english", module: "paper1000", topicId: 5, type: "choice",\n      q: "%s",\n      o: [%s], a: %d,\n      why: "%s",\n      source: "语法1000题·形容词+副词" }' % (i, esc(q), opts, a, esc(why)))

cho(271, "—What colour is the mango?\n—It's ______ .", ["a mango","nice","yellow"], 2, "考查颜色。芒果是什么颜色的可知应选择yellow黄色。故答案选C。")
cho(272, "Will you please give the boy ______ to eat?", ["favorite something","different anything","popular everything","something delicious"], 3, "复合不定代词与形容词连用，要把形容词放在后面，故答案为D。")
cho(273, "Changchun is one of the ______ cities in China.", ["cold","colder","coldest"], 2, "考查形容词最高级。长春是中国最冷的城市之一，故选C。")
cho(274, "Music courses are ______ to me than science courses.", ["interesting","more interesting","interested","more interested"], 1, "要表达“使人感到有趣的”用interesting，后文出现了than，要用比较级，前面加more，故选B。")
cho(275, "She was ______ , and she told us the news ______ .", ["excited; happily","excitedly; happy","excitedly; happily","excited; happy"], 0, "be动词后面加形容词作表语，第一空填excited；第二空填副词修饰told us the news，用happily。故选A。")
cho(276, "______ has Hanmei been in the library?", ["How long","How soon","How far","How often"], 0, "How long表示多久了，用于提问一段时间。has been in表示“已在某地待了多久”。")
cho(277, "The question is ______ for me.", ["easy enough","enough easy","easier enough","enough easier"], 0, "enough作副词修饰形容词时放在形容词后面。")
cho(278, "Tom is ______ than Jack. But I am ______ of the three.", ["tall; tallest","taller, tallest","taller; the tallest"], 2, "两者之间用比较级taller；三者中最高用最高级，最高级前要加the。故选C。")
cho(279, "—______ is Mr. White?\n—He's in the office.", ["Who","Where","What"], 1, "回答位置关系使用特殊疑问词where。故答案为B。")
cho(280, "Which is ______ , singing, dancing or watching TV?", ["relaxing","more relaxing","most relaxing","the most relaxing"], 3, "三者比较，要用形容词最高级the most relaxing，选D。")
cho(281, "Elephants are ______ animals on land.", ["the heaviest","the heavier","the heavy"], 0, "“大象是陆地上最重的动物”，heavy的最高级是the heaviest。故选A。")
cho(282, "Don't be ______ . Let me help you.", ["sad","sadly","excited","excitedly"], 0, "be动词后面接形容词，根据语境选择sad。")
cho(283, "My elder sister is two years ______ than I.", ["older","old","the oldest"], 0, "看到than要用比较级。")
cho(284, "The hamburgers smell ______ ! I like them.", ["salty","healthy","delicious"], 2, "根据空格后面的I like them.可知尝起来很美味，故选C。")
cho(285, "Exercise ______ and smoke ______ is good for your health.", ["most; least","less; more","more; less","least; most"], 2, "考查比较级。句意是：多运动少吸烟有利于你的健康。")
cho(286, "—______ do you go to school?\n— On foot .", ["What","Where","How"], 2, "答句On foot可知问句为“你怎样去学校？”How对方式进行提问。故答案为C。")
cho(287, "______ does Pat brush her teeth? Once a week.", ["How long","How often","How much","What time"], 1, "结合句意“她多久刷一次牙？一周一次”可知，是对刷牙频率进行提问，选择How often。")
cho(288, "I'm 40 kg. You are 46 kg. So you are ______ than me.", ["tall","taller","heavy","heavier"], 3, "考查比较级，重的比较级为heavier。")
cho(289, "It's summer now, the weather is getting ______ .", ["higher and higher","lower and lower","hotter and hotter","colder and colder"], 2, "比较级+and+比较级意为“越来越...”。现在是夏天，天气变得越来越热。")
fill(290, "—______ is the science museum?\n—It's ______ the bank.", "Where；near", "根据句意可知科学博物馆在哪里？它在银行的附近。故答案为：Where；near。")
cho(291, "—______ the cat?\n—It's in the garden.", ["Where's","Who's","What's"], 0, "句意：猫在哪里？它在花园里。问的是地点，故选A。")
cho(292, "The little boy is only three years old. He's ______ young to go to school.", ["enough","very","too","quiet"], 2, "Too...to...是“太...以至于不能...”。他太小了以至于还不能去上学。")
cho(293, "My dress is Size M. Your dress is Size L. Your dress is ______ than ______ .", ["bigger; my","smaller; my","bigger; mine","smaller; mine"], 2, "你的裙子比我的要大，用big的比较级bigger；第二空用名词性物主代词mine作宾语。故答案为C。")
cho(294, "Tom and Jerry are in the ______ school. But they are in different ______ .", ["same, class","same, classes","difference, classes","different, class"], 1, "the same相同的；different后接名词复数classes。所以选B。")
fill(295, "That's the ______ （heavier/heaviest） dinosaur in this hall.", "heaviest", "定冠词the+adj最高级，表示最……。那是大厅里最重的恐龙。故答案为heaviest。")
cho(296, "My mum is ______ in our family.", ["busier","the busiest","busiest","the most busy"], 1, "形容词的最高级前面必须用the。故选B。")
cho(297, "I'm 1.60 metres. You are 1.61 metres. You are ______ than me.", ["shorter","taller","younger"], 1, "根据than可知用比较级。你比我高一点。故选B。")
cho(298, "They are ______ good students that they often get full marks in their exams.", ["a such","such","so a","such a"], 1, "such + 形容词 + 名词 + that。students为复数，用such。")
cho(299, "—The movie is ______ .\n—Yeah, and we are really very ______ when we see it.", ["relaxing; relaxing","relaxed; relaxed","relaxing; relaxed","relaxed; relaxing"], 2, "以-ing结尾的形容词修饰物：令人……；以-ed结尾的形容词修饰人：感到……。电影是令人放松的relaxing；我们感到放松的relaxed。故选C。")
cho(300, "—______ do you go to the cinema with your family?\n---Once a month.", ["How often","How soon","How long","How far"], 0, "How often多久一次问频率。你多久和你的家人去一次看电影？故答案选A。")
cho(301, "Li Ming gets up late every morning, and he ______ late for school.", ["always is","is always","never is","is never"], 1, "频率副词用在be动词的后面；Li Ming每天早上很迟起床，应是总是迟到。故答案选B。")
cho(302, "Of the two sisters, Lucy is ______ one, and she is also the one who loves to be quiet.", ["the younger","a youngest","a younger","the youngest"], 0, "范围是两者用比较级，且在of the two句型中，比较级前要加the。故答案选A。")
cho(303, "Grandma ______ makes chocolate cakes because we don't like chocolate.", ["sometimes","never","often"], 1, "根据不喜欢巧克力的意义得知此处频率为从不。")
cho(304, "This is my elder sister. She is three years ______ than me.", ["old","older","elder","eldest"], 1, "elder指年长的作定语；表示比……年长用older than结构。选B。")
cho(305, "Most dinosaurs are ______ pandas.", ["heavy than","heavier than","heaviest than","heavy more"], 1, "两者之间的比较heavy变成heavier。")
cho(306, "You may be ______ if you have a ______ problem.", ["exciting; worrying","worried; worried","worrying; worried","worried; worrying"], 3, "-ed结尾的形容词修饰人；-ing结尾的修饰“物”。故选D。")
cho(307, "______ apple juice would you like to drink?", ["How many","How much","How","What"], 1, "问数量用how many和how much，apple juice为不可数名词，所以选B。")
cho(308, "I don't need to use much money to buy the phone. It is ______ .", ["cheap","expensive","beautiful"], 0, "不需要花很多钱，说明手机便宜cheap。")
cho(309, "This phone is very big. It's as ______ as a tablet.", ["small","smaller","bigger","big"], 3, "as+原形+as。")
cho(310, "Frank ______ watches movies because they are boring.", ["often","usually","never"], 2, "因为电影很无聊，所以从来不看。")
cho(311, "—______ do you have lunch ?\n—At 12：00 every day.", ["When","Where","Who"], 0, "—什么时候吃午餐？—每天12点。用When提问。故选A。")
cho(312, "Look, it's a ______ （红色的）door.", ["red","blue"], 0, "红色的red。句意：看，这是一扇红色的门。故答案为A。")
cho(313, "Kate is ______ than all of his friends.", ["tall","taller","tallest","the tallest"], 1, "比较级标志词than，tall比较级taller。")
cho(314, "Which is the ______ , the train station, the bus station or the airport?", ["far","farthest","father","more far"], 1, "三个或三个以上物体相互比较，用形容词或副词的最高级。")
fill(315, "连词成句：she does work Where ?", "Where does she work", "特殊疑问句句式：特殊疑问词+助动词+主语+动词原形？does为助动词。故答案为：Where does she work？")
cho(316, "Which is ______ , the sun, the moon or the earth?", ["small","smaller","smallest","the smallest"], 3, "太阳、月亮、地球哪个最小？选最高级the smallest。")
cho(317, "Jack is ______ than Tom, he is ______ boy in the class.", ["tall; taller","taller; taller","taller; the tallest"], 2, "第一个空有than为两者比较用比较级；第二个空in+范围表示在班上最高，用最高级。")
cho(318, "—______ pictures are there on the wall?\n—Five.", ["How many","How much","How long","How often"], 0, "问多少用how many和how much，pictures可数用how many。")
cho(319, "A: ______ does your son go to school?\nB: He always goes to school at seven in the morning.", ["What","Where","When"], 2, "答句说出了上学的时间，所以问句用when提问，选C。")
cho(320, "Is your little sister old ______ to go to school?", ["too","enough","very","quite"], 1, "enough放在名词之后形容词之前。你的小妹妹够大可以去上学了吗？")
cho(321, "The pancake usually tastes ______ .", ["delicious","deliciously","well","wonderfully"], 0, "taste系动词后接形容词delicious。")
cho(322, "I am ______ tall ______ my elder brother.", ["as; so","such; as","as; as","as; such"], 2, "as...as中间加形容词原形。")
cho(323, "My home is ______ of my classmates.", ["bigger","the most biggest","the biggest","big"], 2, "big最高级 the biggest。")
cho(324, "The boy is ______ young to carry the box. Let's go and help him.", ["too","so","very","quite"], 0, "考查too...to do 太……而不能。")
cho(325, "—______ is the girl from?\n—She is ______ the UK.", ["Where's; from","Where; from","Where; in"], 1, "就地点提问用where，问句中be动词is已给出，排除A；“来自”用be from。故选B。")
cho(326, "The ______ you are, the ______ you can work out the math problems.", ["more carefully; more easily","more carefully; easier","more careful; easier","more careful; more easily"], 3, "the+比较级, the+比较级句式；首空修饰人应用形容词more careful；第二空修饰事用easily的比较级more easily。故答案选D。")
cho(327, "To keep a good diet, you should eat ______ fruits and vegetables.", ["more","less","little"], 0, "此处想表达的是吃更多的水果和蔬菜，more表示更多的，符合题意。故选A。")
cho(328, "It was raining ______ when we went out.", ["easily","heavily","heavy","softly"], 1, "考察副词。雨下得很大用heavily。")
cho(329, "Miss Smith doesn't have ______ housework to do today.", ["much","many","a lot","a piece"], 0, "housework为不可数名词，用much来修饰。故选A。")
cho(330, "It's eleven o'clock, but he ______ .", ["still works","still working","is still working","still is working"], 2, "副词still的位置应放在be动词的后面；eleven o'clock是时间点，用进行时。故选C。")
cho(331, "Timmy is one of ______ in Class Two.", ["the tallest boy","the tall boy","the tallest boys","the tall boys"], 2, "one of后用名词复数；最高级前要加the。故选C。")
cho(332, "My brother likes that ______ painting very much.", ["old French interesting","interesting French new","interesting new French"], 2, "多个形容词排序：观点(interesting)＋新旧(new)＋国籍(French)。")
cho(333, "Mike has many good habits. He ______ gets up early in the morning and ______ goes to bed late.", ["always; never","sometimes; always","never; always","often; sometimes"], 0, "迈克有很多好习惯：总是早上很早起床并且从来不会很晚上床睡觉。故答案为A。")
cho(334, "I have ______ .", ["long black hair","black long hair","black long hairs"], 0, "多个形容词排序：长短long在颜色black之前；hair不可数无复数。")
